# Loop every geometry in the ANSYS Mechanical model
i=0
j=0
with Transaction(suspendClicks=True):
    for Assembly in ExtAPI.DataModel.GeoData.Assemblies:
        for Part in Assembly.Parts:
            for Body in Part.Bodies:
                gmBody = gm.GetBody(Body)
                name = gmBody.Name
                slash = name.find("\\")
                if (slash >= 0):
                    ## Rename the geometry
                    name = name[slash+1:]
                else:
                    group = name.find("|Group|")
                    if group >= 0:
                        name = name[group+7:]
                    surface = name.find("|Surface")
                    if surface >= 0:
                        name = name[:surface]
                    pipe = name.find("|")
                    if (pipe >= 0):
                        ## Rename the geometry
                        name = name[pipe+1:]
                    if surface >= 0 or group >= 0:
                        name = re.sub('\[\d+\]$','',name)
                        if nameInstanceCounts.Contains(name):
                            nameInstanceCounts[name] += 1
                            name = name + "[" + str(nameInstanceCounts[name]) + "]"
                        else:
                            nameInstanceCounts[name] = 1

                gmBody.Name = name
                geometryNameMap[name] = [i, j]
                geometryBody[(i,j)] = gmBody
                j = j + 1
            i = i + 1

etime = time.time() - stime
